SELECT state, city, num_call_centers, num_web_sites, avg_cc_tax, avg_ws_tax, tax_pct_diff, total_employees, RANK() OVER (PARTITION BY state ORDER BY total_employees DESC) AS employee_rank_by_state FROM ( SELECT cc.cc_state AS state, cc.cc_city AS city, COUNT(DISTINCT cc.cc_call_center_sk) AS num_call_centers, COUNT(DISTINCT ws.web_site_sk) AS num_web_sites, AVG(cc.cc_tax_percentage) AS avg_cc_tax, AVG(ws.web_tax_percentage) AS avg_ws_tax, AVG(cc.cc_tax_percentage) - AVG(ws.web_tax_percentage) AS tax_pct_diff, SUM(cc.cc_employees) AS total_employees FROM call_center cc JOIN web_site ws ON cc.cc_state = ws.web_state AND cc.cc_city = ws.web_city WHERE cc.cc_rec_start_date >= DATE '2000-01-01' AND ws.web_rec_start_date >= DATE '2000-01-01' AND cc.cc_tax_percentage IS NOT NULL AND ws.web_tax_percentage IS NOT NULL GROUP BY cc.cc_state, cc.cc_city HAVING COUNT(DISTINCT cc.cc_call_center_sk) > 0 ) t ORDER BY tax_pct_diff DESC LIMIT 100
